mapper.select:
select * from ( select o.id, g.id glueGroupId, g.glue_group_code, g.glue_group_name, o.glue_code, o.order_num, g.order_num||'.'||o.order_num as glue_group_order_num, o.remark from T_TC_GLUE_GROUP_ORDER g inner join T_TC_GLUE_ORDER o on g.id = o.glue_group_id where 1=1 and g.del_flag=0 and o.del_flag=0
and GLUE_GROUP_ID = #{glueGroupId}
and INSTR(GLUE_CODE, #{glueCode}) > 0
order by g.order_num, o.order_num
) t
order by ${orderStr}

mapper.update:
merge into T_TC_GLUE_ORDER a USING (
select #{item.glueCode,jdbcType=VARCHAR} GLUE_CODE, #{item.glueGroupId,jdbcType=DOUBLE} GLUE_GROUP_ID, #{item.orderNum,jdbcType=DOUBLE} ORDER_NUM, #{item.createBy,jdbcType=VARCHAR} create_by, #{item.createTime,jdbcType=DATE} create_time, #{item.updateBy,jdbcType=VARCHAR} update_by, #{item.updateTime,jdbcType=DATE} update_time, #{item.remark,jdbcType=VARCHAR} remark from dual
) b ON ( a.GLUE_CODE = b.GLUE_CODE AND a.del_flag = '0' ) WHEN MATCHED THEN UPDATE SET a.GLUE_GROUP_ID = b.GLUE_GROUP_ID, a.ORDER_NUM = b.ORDER_NUM, a.update_by = b.create_by, a.update_time = sysdate, a.remark = b.remark WHEN NOT MATCHED THEN INSERT (a.id, a.glue_code, a.GLUE_GROUP_ID, a.ORDER_NUM, a.create_by, a.create_time, a.remark,a.del_flag) values (SEQ_PUBLIC.NEXTVAL, b.glue_code, b.GLUE_GROUP_ID, b.ORDER_NUM, b.create_by, sysdate, b.remark,'0')
